function dedupe<T extends {url:string}>(items:T[]):T[]{return [...new Map(items.map(item=>[canonical(item.url),item])).values()]}
function fredUrl(id:string,months:number){const start=new Date(Date.now()-months*31*86400000).toISOString().slice(0,10);return `${FRED}?id=${encodeURIComponent(id)}&cosd=${start}`}
export function parseFredCsv(csv:string,id:string,url:string):Point[]{const lines=csv.replace(/^\uFEFF/,'').trim().split(/\r?\n/).filter(Boolean);if(lines.length<2)return [];const header=parseCsvRow(lines[0]!),dateIndex=header.findIndex(value=>/^(?:observation_date|date)$/i.test(value.trim())),valueIndex=header.findIndex(value=>value.trim().toUpperCase()===id.toUpperCase());if(dateIndex<0||valueIndex<0)return [];const points:Point[]=[];for(const line of lines.slice(1)){const fields=parseCsvRow(line),date=fields[dateIndex]?.trim()??'',raw=fields[valueIndex]?.trim().replaceAll(',','')??'';if(!raw||raw==='.')continue;const value=Number(raw);if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(value))points.push({date,value,sourceId:'FRED:'+id,sourceUrl:url})}return points}
function parseCsvRow(row:string):string[]{const fields:string[]=[];let current='',quoted=false;const push=()=>{fields.push(current);current=''};for(let index=0;index<row.length;index++){const char=row[index]!;if(char==='"'){if(quoted&&row[index+1]==='"'){current+='"';index++}else quoted=!quoted;continue}if(char===','&&!quoted){push();continue}current+=char}push();return fields}
export function parseYahooUsChart(body:unknown,symbol:string,url:string):Point[]{const chart=(body as {chart?:{result?:Array<{timestamp?:number[];indicators?:{quote?:Array<{close?:Array<number|null>}>}}>}}).chart,result=chart?.result?.[0],timestamps=result?.timestamp??[],closes=result?.indicators?.quote?.[0]?.close??[],points:Point[]=[];for(let index=0;index<timestamps.length;index++){const timestamp=timestamps[index],value=closes[index];if(typeof timestamp!=='number'||typeof value!=='number'||!Number.isFinite(value))continue;const date=new Date(timestamp*1000).toISOString().slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(date))points.push({date,value,sourceId:'YAHOO:'+symbol,sourceUrl:url})}return points.sort((a,b)=>a.date.localeCompare(b.date))}
export function parseTreasuryTenYearXml(xml:string,url:string):Point[]{const entries=[...xml.matchAll(/<entry\b[\s\S]*?<\/entry>/gi)],points:Point[]=[];for(const match of entries){const block=match[0],dateRaw=block.match(/<d:NEW_DATE[^>]*>([^<]+)<\/d:NEW_DATE>/i)?.[1]?.trim()??'',valueRaw=block.match(/<d:BC_10YEAR[^>]*>([^<]+)<\/d:BC_10YEAR>/i)?.[1]?.trim()??'',date=dateRaw.slice(0,10),value=Number(valueRaw);if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(value))points.push({date,value,sourceId:'TREASURY:10Y',sourceUrl:url})}return points.sort((a,b)=>a.date.localeCompare(b.date))}
function usProvider(url:string){if(url.includes('query1.finance.yahoo.com'))return {label:'Yahoo Finance',publisher:'Yahoo Finance'};if(url.includes('home.treasury.gov'))return {label:'U.S. Treasury',publisher:'U.S. Department of the Treasury'};if(url.includes('twelvedata.com'))return {label:'Twelve Data',publisher:'Twelve Data'};return {label:'FRED',publisher:'Federal Reserve Bank of St. Louis'}}
function recentObservation(observed:string,sessionDate:string){const days=(Date.parse(sessionDate+'T00:00:00Z')-Date.parse(observed+'T00:00:00Z'))/86400000;return days>=0&&days<=4}
export function buildUSEditorialTitleCandidates(history:USMarketDailyViewModel['marketHistory'],metrics:NewsletterMarketMetric[]):string[]{
 const core=history.series.filter(item=>['sp500','nasdaq','dow-jones'].includes(item.key)&&Number.isFinite(item.latestChangePct));
 if(core.length<3)throw new Error('US_EDITORIAL_TITLE_INPUT_INSUFFICIENT');
 const largest=[...core].sort((a,b)=>Math.abs(b.latestChangePct)-Math.abs(a.latestChangePct))[0]!,indexMove=largest.latestChangePct>0?'상승':largest.latestChangePct<0?'하락':'보합',up=core.filter(item=>item.latestChangePct>0).length,down=core.filter(item=>item.latestChangePct<0).length,breadth=up===core.length?'동반 상승':down===core.length?'동반 하락':'혼조',tenYear=metrics.find(item=>item.label.includes('미국 10년물')&&!item.label.includes('기준'));
 if(!tenYear){const led=breadth==='혼조'?`${largest.label} 중심으로 엇갈린 미국 주요 지수`:`${largest.label} 중심으로 ${breadth}한 미국 주요 지수`;return [`${largest.label} ${indexMove}, 미국 주요 지수 ${breadth}`, `미국증시 ${breadth}, ${largest.label} 움직임이 두드러졌다`, led]}
 const rateMove=tenYear.direction==='UP'?'상승':tenYear.direction==='DOWN'?'하락':'보합',relation=(largest.latestChangePct>0&&tenYear.direction==='UP')||(largest.latestChangePct<0&&tenYear.direction==='DOWN')?'맞물린':'엇갈린';
 return [`${largest.label} ${indexMove}, 장기금리 ${rateMove} 속 미국증시`, `미국 주요 지수 ${breadth}, ${largest.label} 움직임에 시선`, `장기금리 ${rateMove}과 ${largest.label} ${indexMove}이 ${relation} 흐름`];
}
function rss(xml:string){const entries=[...xml.matchAll(/<(?:item|entry)\b[\s\S]*?<\/(?:item|entry)>/gi)],read=(block:string,names:string[])=>{for(const name of names){const match=block.match(new RegExp(`<${name}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${name}>`,'i'));if(match)return clean(match[1]!)}return ''};return entries.map(match=>{const block=match[0],href=block.match(/<link[^>]*href=["']([^"']+)/i)?.[1]??read(block,['link']);return {title:read(block,['title']),link:href,publishedAt:read(block,['pubDate','published','updated']),summary:read(block,['description','summary','content'])}}).filter(item=>item.title&&/^https?:\/\//.test(item.link))}
function kMetric(factId:string,group:KoreaMarketNewsletterMetric['group'],label:string,value:number,change:number,url:string):KoreaMarketNewsletterMetric{return {factId,group,label,displayValue:group==='INDEX'||group==='FX'?format(value):(change>=0?'+':'')+format(value),direction:direction(change),source:{label:'네이버금융',url}}}
function kstDate(value:string){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value)),get=(type:string)=>parts.find(part=>part.type===type)?.value??'';return `${get('year')}-${get('month')}-${get('day')}`}
function metricMagnitude(metric:KoreaMarketNewsletterMetric){const parsed=Number(metric.displayValue.replace(/[^0-9.-]/g,''));return Number.isFinite(parsed)?Math.abs(parsed):0}
function percent(value:number,previous:number){const change=(value-previous)/previous*100;return `${change>=0?'+':''}${change.toFixed(2)}%`}
function direction(value:number):'UP'|'DOWN'|'FLAT'{return value>0?'UP':value<0?'DOWN':'FLAT'}
function format(value:number){return new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(value)}
function clean(value:string){return value.replace(/<!\[CDATA\[|\]\]>/g,'').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&#(x[0-9a-f]+|[0-9]+);/gi,(entity,digits:string)=>{const code=digits[0]!.toLowerCase()==='x'?parseInt(digits.slice(1),16):Number(digits);return code>0&&code<=0x10ffff?String.fromCodePoint(code):entity}).replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/\s+/g,' ').trim()}
function extractPageEvidence(html:string):string {const descriptions=[...html.matchAll(/<meta\b[^>]*(?:name|property)=["'](?:description|og:description)["'][^>]*content=["']([^"']+)["'][^>]*>/gi)].map(match=>clean(match[1]!)),paragraphs=[...html.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)].map(match=>clean(match[1]!)).filter(value=>value.length>=60);return [...descriptions,...paragraphs].find(value=>value.length>=80)?.slice(0,700)??''}
function koreanCompany(value:string):string {return ({OpenAI:'오픈AI','Google AI':'구글',NVIDIA:'엔비디아',Microsoft:'마이크로소프트'} as Record<string,string>)[value]??value}
function canonical(value:string){try{const url=new URL(value);url.hash='';for(const key of [...url.searchParams.keys()])if(/^utm_/i.test(key))url.searchParams.delete(key);return url.toString()}catch{return value.trim().toLowerCase()}}
function message(error:unknown){return error instanceof Error?error.message:String(error)}

// Offset timestamps represent instants; compact provider dates already use the Korean session calendar.
export function koreaReferenceDate(value:string|undefined):string {
 const raw=value??'';
 if(/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:?\d{2})$/.test(raw)){
  const instant=Date.parse(raw);return Number.isFinite(instant)?new Date(instant+9*3600000).toISOString().slice(0,10):'';
 }
 if(/^\d{8}(?:\d{6})?$/.test(raw))return raw.slice(0,8).replace(/^(\d{4})(\d{2})(\d{2})$/,'$1-$2-$3');
 return /^\d{4}-\d{2}-\d{2}(?:T|$)/.test(raw)?raw.slice(0,10):'';
}
function recordKoreaDate(audit:InternalSourceAuditEntry[],sourceId:string,dateField:string,sourceTimestamp:string|undefined):string {
 const observedDate=koreaReferenceDate(sourceTimestamp),entry=[...audit].reverse().find(item=>item.sourceId===sourceId);
 if(entry){entry.dateField=dateField;entry.sourceTimestamp=sourceTimestamp??'';entry.observedDate=observedDate;}
 return observedDate;
}

const AI_WINDOW_MS=96*3600000,AI_MAX_PAGE_FETCHES=10,AI_MAX_ISSUES=3;
const AI_TYPE_WEIGHT:Record<AIEventType,number>={infrastructure:3,launch:3,partnership:3,investment:3,adoption:2,policy:2,security:2,education:1,research:1};
type SelectableAIEvent={topicId:string;publisher:string;publishedAt:string;basis:AIEvidenceBasis;eventType:AIEventType;richness?:number};
/** Lead must rest on full first-party text; RSS-summary items may only support. One item per publisher first, then fill. */
export function selectAIEvents<T extends SelectableAIEvent>(events:T[]):T[] {
 const score=(event:T)=>(event.basis==='OFFICIAL_PAGE'?4:0)+AI_TYPE_WEIGHT[event.eventType]+(event.richness??0)+Math.max(0,1-(Date.now()-Date.parse(event.publishedAt))/AI_WINDOW_MS);
 const ranked=[...events].sort((a,b)=>score(b)-score(a)),lead=ranked.find(event=>event.basis==='OFFICIAL_PAGE');
 if(!lead)return [];
 const chosen=[lead];
 for(const event of ranked)if(chosen.length<AI_MAX_ISSUES&&!chosen.includes(event)&&!chosen.some(item=>item.publisher===event.publisher))chosen.push(event);
 for(const event of ranked)if(chosen.length<AI_MAX_ISSUES&&!chosen.includes(event))chosen.push(event);
 return chosen;
}
/**
 * Source links already covered by a PUBLISHED AI operation. Read from the immutable publish ledger
 * (sourceUrls recorded at publication); a legacy entry without them falls back to the persisted live unit
 * only when that unit is provably the published one (content fingerprint equals the ledger fingerprint).
 */
async function previouslyPublishedAILinks(operationsRoot:string):Promise<Set<string>> {
 const links=new Set<string>();let dates:string[]=[];
 try{dates=(await readdir(operationsRoot)).filter(name=>/^\d{4}-\d{2}-\d{2}$/.test(name))}catch{return links}
 for(const date of dates){
  const root=join(operationsRoot,date,'ai');let ledger='';try{ledger=await readFile(join(root,'publish-ledger.jsonl'),'utf8')}catch{continue}
  const published=ledger.split(/\r?\n/).filter(Boolean).map(line=>{try{return JSON.parse(line) as {event?:string;fingerprint?:string;sourceUrls?:unknown}}catch{return null}}).filter((entry):entry is {event?:string;fingerprint?:string;sourceUrls?:unknown}=>Boolean(entry&&entry.event==='PUBLISHED'));
  for(const entry of published){
   if(Array.isArray(entry.sourceUrls)){for(const url of entry.sourceUrls)if(typeof url==='string')links.add(canonical(url));continue}
   try{const unit=JSON.parse(await readFile(join(root,'live-unit.json'),'utf8')) as {contentFingerprint?:unknown;viewModel?:{sources?:Array<{url?:unknown}>}};if(typeof unit.contentFingerprint==='string'&&'sha256:'+unit.contentFingerprint===entry.fingerprint)for(const source of unit.viewModel?.sources??[])if(typeof source.url==='string')links.add(canonical(source.url))}catch{}
  }
 }
 return links;
}
